XC = "Xcode 27 is installed. Build checks use `xcodebuild` for the iOS Simulator only (no signing): `xcodebuild -project ios/WebbWheresMyCar.xcodeproj -scheme WebbWheresMyCar -sdk iphonesimulator -destination 'generic/platform=iOS Simulator' CODE_SIGNING_ALLOWED=NO build`."
CARDS = [
 dict(id="I01", title="iOS wrapper: Swift sources", needs=["W51"],
  files=["ios/Sources/AppDelegate.swift", "ios/Sources/GameViewController.swift", "ios/Sources/AssetSchemeHandler.swift", "ios/Info.plist"],
  goal="The native iPhone shell for the web game: a full-screen WKWebView that serves the bundled game files through a custom `webb://` URL scheme (ES modules do not load from file:// in WKWebView).",
  read=["index.html and src/boot.js (how the game starts in a browser)", "docs/DESIGN.md section 1 (landscape 1280x720 game, canvas letterboxed)"],
  steps=[
   "`AssetSchemeHandler.swift`: `final class AssetSchemeHandler: NSObject, WKURLSchemeHandler` with `init(root: URL)`. `webView(_:start:)`: take `task.request.url?.path`; `/` means `/index.html`; reject any path containing `..` with a 404; read the file under `root` with `Data(contentsOf:)`; answer with an `HTTPURLResponse` (status 200, HTTP/1.1) with `Content-Type` from the extension (html `text/html; charset=utf-8`, js and mjs `text/javascript; charset=utf-8`, json and webmanifest `application/json`, css `text/css`, png `image/png`, jpg `image/jpeg`, svg `image/svg+xml`, woff2 `font/woff2`, woff `font/woff`, ttf `font/ttf`, mp3 `audio/mpeg`, wav `audio/wav`, otherwise `application/octet-stream`), `Content-Length` and `Access-Control-Allow-Origin: *`; then `didReceive(response)`, `didReceive(data)`, `didFinish()`. A missing file: status 404 with an empty body. `webView(_:stop:)` does nothing.",
   "`GameViewController.swift`: `final class GameViewController: UIViewController`. In `viewDidLoad` build a `WKWebViewConfiguration`: `setURLSchemeHandler(AssetSchemeHandler(root: <Bundle.main.resourceURL>/www), forURLScheme: \"webb\")`, `allowsInlineMediaPlayback = true`, `mediaTypesRequiringUserActionForPlayback = []`; create the `WKWebView` filling the view (black background, `isOpaque = false`, `scrollView.isScrollEnabled = false`, `scrollView.bounces = false`, `scrollView.contentInsetAdjustmentBehavior = .never`), `isInspectable = true` in DEBUG builds only, and `load(URLRequest(url: URL(string: \"webb://app/index.html\")!))`. Override `supportedInterfaceOrientations` -> `.landscape`, `prefersStatusBarHidden` -> true, `prefersHomeIndicatorAutoHidden` -> true, `shouldAutorotate` -> true.",
   "`AppDelegate.swift`: `@main final class AppDelegate: UIResponder, UIApplicationDelegate` that creates a `UIWindow` with `GameViewController` as root (no storyboard) in `application(_:didFinishLaunchingWithOptions:)` and returns true; implement `application(_:supportedInterfaceOrientationsFor:)` -> `.landscape`.",
   "`ios/Info.plist` (XML plist): `CFBundleDevelopmentRegion` en, `CFBundleDisplayName` `Webb Wheels`, `CFBundleExecutable` `$(EXECUTABLE_NAME)`, `CFBundleIdentifier` `$(PRODUCT_BUNDLE_IDENTIFIER)`, `CFBundleName` `$(PRODUCT_NAME)`, `CFBundlePackageType` `APPL`, `CFBundleShortVersionString` `$(MARKETING_VERSION)`, `CFBundleVersion` `$(CURRENT_PROJECT_VERSION)`, `LSRequiresIPhoneOS` true, `UIRequiresFullScreen` true, `UISupportedInterfaceOrientations` = [`UIInterfaceOrientationLandscapeLeft`, `UIInterfaceOrientationLandscapeRight`], `UIStatusBarHidden` true, `UIViewControllerBasedStatusBarAppearance` true, `ITSAppUsesNonExemptEncryption` false, `UILaunchScreen` as an empty dict. Check it with `plutil -lint ios/Info.plist`."],
  accept=["`plutil -lint ios/Info.plist` prints OK.", "`xcrun swiftc -typecheck -sdk $(xcrun --sdk iphonesimulator --show-sdk-path) -target arm64-apple-ios16.0-simulator ios/Sources/*.swift` exits 0 with no errors."]),

 dict(id="I02", title="iOS wrapper: Xcode project generator", needs=["I01"],
  files=["ios/make_project.py", "ios/Assets.xcassets/Contents.json", "ios/Assets.xcassets/AppIcon.appiconset/Contents.json", "ios/.gitignore"],
  goal="A python script that writes `ios/WebbWheresMyCar.xcodeproj/project.pbxproj`, so the Xcode project is generated, not hand-edited.",
  read=[XC, "ios/Sources/*.swift and ios/Info.plist (from I01)"],
  steps=[
   "`ios/make_project.py` (python3 standard library only; run from the repo root) writes `ios/WebbWheresMyCar.xcodeproj/project.pbxproj` (create the folder). One app target `WebbWheresMyCar`, product `WebbWheresMyCar.app`, bundle identifier `com.leelangley.webbwheresmycar`, `DEVELOPMENT_TEAM = G3G9X5XV82`, `CODE_SIGN_STYLE = Automatic`, `IPHONEOS_DEPLOYMENT_TARGET = 16.0`, `TARGETED_DEVICE_FAMILY = 1` (iPhone only), `SWIFT_VERSION = 5.0`, `MARKETING_VERSION = 0.1`, `CURRENT_PROJECT_VERSION` from the env var `BUILD_NUMBER` (default `1`), `INFOPLIST_FILE = Info.plist`, `ASSETCATALOG_COMPILER_APPICON_NAME = AppIcon`, `GENERATE_INFOPLIST_FILE = NO`. Sources build phase: the three Swift files in `Sources/`. Resources build phase: `Assets.xcassets` and a FOLDER REFERENCE to `www` (`lastKnownFileType = folder`, so the whole folder is copied into the bundle as `www/`). Object ids: 24 hex characters made deterministically from `md5(name)`. Also write the shared scheme `ios/WebbWheresMyCar.xcodeproj/xcshareddata/xcschemes/WebbWheresMyCar.xcscheme` so `-scheme WebbWheresMyCar` works.",
   "Create `ios/Assets.xcassets/Contents.json` (`{\"info\":{\"version\":1,\"author\":\"xcode\"}}`) and `ios/Assets.xcassets/AppIcon.appiconset/Contents.json` for the single-size 1024 universal iOS icon (`\"images\":[{\"idiom\":\"universal\",\"platform\":\"ios\",\"size\":\"1024x1024\",\"filename\":\"icon-1024.png\"}]`). Make the PNG with `sips -z 1024 1024 assets/icons/icon-512.png --out ios/Assets.xcassets/AppIcon.appiconset/icon-1024.png` (a placeholder; a better icon comes later).",
   "`ios/.gitignore`: `www/`, `build/`, `*.xcarchive`. The script creates an empty `ios/www/index.html` if `ios/www` is missing so the project builds on its own. Run the script, then the simulator build command from Read-first: it must print `BUILD SUCCEEDED`. Commit the generated `ios/WebbWheresMyCar.xcodeproj` too."],
  accept=["`python3 ios/make_project.py && xcodebuild -project ios/WebbWheresMyCar.xcodeproj -scheme WebbWheresMyCar -sdk iphonesimulator -destination 'generic/platform=iOS Simulator' CODE_SIGNING_ALLOWED=NO build 2>&1 | tail -3` shows `BUILD SUCCEEDED`."]),

 dict(id="I03", title="iOS wrapper: copy the game into the app", needs=["I01", "W51"],
  files=["tools/ios/sync_www.sh", "tests/run_sync_www.sh"],
  goal="A script that copies the web game into `ios/www/` (the folder the app bundles).",
  read=["index.html, src/, assets/ (what the browser version loads)", "ios/.gitignore (www/ is ignored)"],
  steps=[
   "`tools/ios/sync_www.sh` (sh; `cd` to the repo root first): `rm -rf ios/www && mkdir -p ios/www`; copy `index.html`, `manifest.webmanifest` and `sw.js` when they exist, the whole `src/` folder, and `assets/` EXCEPT `assets/art/preview` and anything under `build/`; never copy `docs`, `tests`, `tools`, `cards`, `.git`. If `index.html` is missing exit 1 with a message. Print `SYNCED <n> files` (n = number of files under ios/www).",
   "`tests/run_sync_www.sh`: runs the script, requires exit 0, that `ios/www/index.html` and `ios/www/src/main.js` exist, that `ios/www/docs`, `ios/www/tests`, `ios/www/tools`, `ios/www/cards` and `ios/www/assets/art/preview` do not exist; prints `SYNC WWW OK`. (`ios/www` is git-ignored: do not commit it.)"],
  accept=["`sh tests/run_sync_www.sh` prints `SYNC WWW OK`."]),

 dict(id="I04", title="iOS wrapper: TestFlight build script", needs=["I02", "I03"],
  files=["tools/ios/testflight.sh", "tools/ios/ExportOptions.plist"],
  goal="Two commands: `build <name>` makes an unsigned archive of the app; `upload <name>` signs it and sends it to App Store Connect (TestFlight). It copies the approach of Lee's script `~/Documents/Christs of Rage/tools/ios/testflight.sh` (read it first). Never read or print any Apple key or password.",
  read=["~/Documents/Christs of Rage/tools/ios/testflight.sh and ExportOptions.plist (the working example: copy its upload() retry loop and its ASC_KEY_PATH / ASC_KEY_ID / ASC_ISSUER_ID handling)", "ios/make_project.py (I02) and tools/ios/sync_www.sh (I03)", XC],
  steps=[
   "`tools/ios/testflight.sh` (bash, `set -u`, header comment explaining usage). `build <name>`: `cd` to the repo root; `sh tools/ios/sync_www.sh`; build number `N` = `date +%y%m%d%H%M` (digits only, always increasing); `BUILD_NUMBER=$N python3 ios/make_project.py`; `xcodebuild -project ios/WebbWheresMyCar.xcodeproj -scheme WebbWheresMyCar -configuration Release -sdk iphoneos -archivePath /tmp/WebbWheresMyCar-<name>.xcarchive CODE_SIGNING_ALLOWED=NO archive`; print the archive path and N. `upload <name>`: needs that archive; export and upload with `xcodebuild -exportArchive -archivePath <archive> -exportOptionsPlist tools/ios/ExportOptions.plist -exportPath /tmp/WebbWheresMyCar-export-<name> -allowProvisioningUpdates` PLUS the API key arguments `-authenticationKeyPath $ASC_KEY_PATH -authenticationKeyID $ASC_KEY_ID -authenticationKeyIssuerID $ASC_ISSUER_ID` when those three env vars are set (the caller runs `source ~/.appstoreconnect/rage.env` first); retry every 30 seconds up to 20 times; print `UPLOAD DONE` on success and `ALREADY AT APPLE` when the log says the build was already uploaded. No arguments or an unknown command: print usage, exit 2.",
   "`tools/ios/ExportOptions.plist`: `method` `app-store-connect`, `destination` `upload`, `teamID` `G3G9X5XV82`, `signingStyle` `automatic`, `uploadSymbols` true, `manageAppVersionAndBuildNumber` false. Check with `plutil -lint`.",
   "Test only the unsigned build: `bash tools/ios/testflight.sh build ci1` and confirm `/tmp/WebbWheresMyCar-ci1.xcarchive` exists. If the unsigned device archive fails with a signing message, report the exact error in your summary and add `CODE_SIGN_IDENTITY=\"\"` to the build command. Do NOT run `upload`."],
  accept=["`plutil -lint tools/ios/ExportOptions.plist` prints OK.", "`bash tools/ios/testflight.sh` with no arguments prints usage and exits 2.", "`bash tools/ios/testflight.sh build ci1` ends with the archive path (report the exact output)."]),

 dict(id="I05", title="iOS wrapper: instructions for Lee", needs=["I04"],
  files=["docs/IOS.md"],
  goal="A short, exact guide so Lee can put the game on his iPhone through TestFlight.",
  read=["tools/ios/testflight.sh and ios/ (previous cards)", "~/Documents/Christs of Rage/HANDOFF.md lines about TestFlight (how Lee ships Rage of Christ)"],
  steps=[
   "Write `docs/IOS.md` (plain ASCII markdown, 30 to 70 lines): (1) ONE-TIME: in App Store Connect create a new app named `Webb, where's my car?`, bundle id `com.leelangley.webbwheresmycar` (it must be registered first; automatic signing with the API key can register it), SKU `webbwheresmycar`, primary language English (UK); add the internal TestFlight group `Lee`. (2) EACH BUILD: a `git worktree` of the commit to ship, then `source ~/.appstoreconnect/rage.env`, `bash tools/ios/testflight.sh build <name>`, `bash tools/ios/testflight.sh upload <name>`; wait 10-15 minutes for Apple to process; open TestFlight on the iPhone and press Install or Update. (3) Simulator check with no account: the simulator xcodebuild command, then `xcrun simctl boot`, `xcrun simctl install booted <path to .app>`, `xcrun simctl launch booted com.leelangley.webbwheresmycar`. (4) A troubleshooting table: not signed in or key rejected -> check the three env vars (never print them); build number too low -> run build again (the number is the date and time); blank screen -> run `sh tools/ios/sync_www.sh` and check `ios/www/index.html`; no sound until the first tap (an iOS rule). State that no Apple password is ever typed by an assistant."],
  accept=["`wc -l docs/IOS.md` is between 30 and 70 and `grep -nP '[^\\x00-\\x7F]' docs/IOS.md` prints nothing."]),
]
